corpus_block("test-stat-bin.R: stat_bin() provides width (#3522)", {
  binwidth <- 1.03
  df <- data_frame(x = 1:10)
  .plot("test-stat-bin.R: stat_bin() provides width (#3522) #1", p <- ggplot(df) +
      stat_bin(
        aes(
          x,
          xmin = after_stat(x - width / 2),
          xmax = after_stat(x + width / 2),
          ymin = after_stat(0),
          ymax = after_stat(count)
        ),
        geom = "rect",
        binwidth = binwidth
      ))
  out <- get_layer_data(p)
})

